    #[test]
    fn jit_break_continue() {
        let src = r#"
            fn main() -> i64 {
                let mut i = 0
                let mut acc = 0
                while i < 100 {
                    i += 1
                    if i == 5 { continue }
                    if i == 10 { break }
                    acc += i
                }
                acc
            }
        "#;
        // 1+2+3+4 + 6+7+8+9 = 10 + 30 = 40
        assert_eq!(jit_run_i64(src).unwrap(), 40);
    }

