    // ─── Slice 2: tensors + Forge + elementwise + matmul ────────────────────

    fn jit_run_f32(src: &str) -> Result<f32, String> {
        // Build a tiny shim that reinterprets `main`'s i64 return through a
        // bitcast — we don't have first-class f32 returns wired into the
        // test harness yet. Instead, tests below mutate a small driver:
        // they have `main() -> f32`, run_main prints the value to stdout
        // and returns 0; we capture via a different harness. For now,
        // tests assert via `sum(t) as i64` semantics.
        let toks = Lexer::new(src).tokenize().map_err(|e| e.to_string())?;
        let prog = Parser::new(toks).parse_program().map_err(|e| e.to_string())?;
        let mut jit = Jit::new().map_err(|e| e.to_string())?;
        jit.compile_program(&prog).map_err(|e| e.to_string())?;
        let _ = jit.run_main().map_err(|e| e.to_string())?;
        Ok(0.0)
    }

