        assert_eq!(e.kind, JitErrorKind::Unsupported, "{}", e);
        assert_eq!(e.refusal.map(|r| r.code()), Some("jit-conversion"), "{}", e);
        assert!(e.msg.contains("cannot convert `i64?` to `KV[f32, [~, 4]]`"), "{}", e);
        assert!(e.msg.contains("#721"), "{}", e);
