    // ─── FOMAML (First-Order MAML) ───────────────────────────────────────────

    #[test]
    fn jit_fomaml_basic() {
        // FOMAML: an outer @grad fn calls an inner @grad fn's fwd_bwd,
        // treats the resulting gradient as a stop-gradient leaf, uses it to
        // compute an adapted weight W1 = W - 0.5 .* g.W, and returns a loss
        // on the adapted weight. The outer gradient should be nonzero.
        //
        // inner_step: loss = sum(W .* support)   → dW = support (elementwise)
        // outer_loss(W, support):
        //   (_, g)  = inner_step.fwd_bwd(W, support)   # g.W = support (stop-grad)
        //   W1      = W .- g.W .* 0.5                  # W1 = W - 0.5*support
        //   sum(W1 .* W1)
        //
        // d(outer_loss)/dW = 2*(W - 0.5*support).
        // With W=[1,1], support=[1,1]:
        //   g.W = [1,1] (stop-gradient, so no gradient flows through it)
        //   W1 = [0.5, 0.5], loss = 0.5
        //   dW = 2*[0.5,0.5] = [1.0, 1.0]
        let src = r#"
            @grad fn inner_step(!W: Tensor[f32, [2]], support: Tensor[f32, [2]]) -> f32 {
                sum(W .* support)
            }
            @grad fn outer_loss(!W: Tensor[f32, [2]], support: Tensor[f32, [2]]) -> f32 {
                let (_, g) = inner_step.fwd_bwd(W, support)
                let W1 = W .- g.W .* 0.5
                sum(W1 .* W1)
            }
        "#;
        let w       = [1.0_f32, 1.0];
        let support = [1.0_f32, 1.0];
        let (loss, grads) = jit_grad(src, "outer_loss", &[&w, &support], &[2]).unwrap();
        // W1 = [0.5, 0.5]; loss = 0.25 + 0.25 = 0.5
        assert!(approx(loss, 0.5), "expected loss=0.5, got {}", loss);
        // d/dW = 2*(W - 0.5*support) = 2*[0.5,0.5] = [1.0, 1.0]
        assert!(approx(grads[0][0], 1.0), "dW[0] expected 1.0, got {:?}", grads[0]);
        assert!(approx(grads[0][1], 1.0), "dW[1] expected 1.0, got {:?}", grads[0]);
    }

    #[test]
    fn jit_fomaml_discard_grad() {
        // `let (loss, _) = inner.fwd_bwd(...)` inside a @grad fn should
        // compile and run fine; the gradient is simply discarded.
        // The outer @grad fn has its own mut param W that IS differentiated.
        //
        // outer: loss = inner_loss + sum(W .* W)
        //   inner_loss = sum(W.*W) (via fwd_bwd, stop-gradient)
        //   d(outer_loss)/dW comes only from sum(W.*W) term => dW = 2W
        let src = r#"
            @grad fn inner(!W: Tensor[f32, [2]]) -> f32 {
                sum(W .* W)
            }
            @grad fn outer(!W: Tensor[f32, [2]]) -> f32 {
                let (inner_loss, _) = inner.fwd_bwd(W)
                inner_loss + sum(W .* W)
            }
        "#;
        let w = [1.0_f32, 2.0];
        let (loss, grads) = jit_grad(src, "outer", &[&w], &[2]).unwrap();
        // inner_loss = 1+4 = 5; sum(W.*W) = 5; outer loss = 10
        assert!(approx(loss, 10.0), "expected loss=10.0, got {}", loss);
        // dW only from sum(W.*W) term (inner_loss is stop-grad) = 2*W = [2,4]
        assert!(approx(grads[0][0], 2.0), "dW[0] expected 2.0, got {:?}", grads[0]);
        assert!(approx(grads[0][1], 4.0), "dW[1] expected 4.0, got {:?}", grads[0]);
    }

    #[test]
    fn jit_grad_sigmoid() {
        // Finite-difference cross-check for sigmoid gradient inside @grad fn.
        // loss = sum(sigmoid(W .* x))
        // d/dW[sigmoid(w*x)] = sigmoid(w*x)*(1 - sigmoid(w*x)) * x
        let src = r#"
            @grad fn loss(!W: Tensor[f32, [3]], x: Tensor[f32, [3]]) -> f32 {
                sum(sigmoid(W .* x))
            }
        "#;
        let w0 = [0.1_f32, 0.2, 0.3];
        let x  = [1.0_f32, 1.0, 1.0];
        let eps = 1e-3_f32;
        let (_, grads) = jit_grad(src, "loss", &[&w0, &x], &[3]).unwrap();
        for k in 0..3 {
            let mut wp = w0;
            wp[k] += eps;
            let src2 = r#"
                @grad fn loss(!W: Tensor[f32, [3]], x: Tensor[f32, [3]]) -> f32 {
                    sum(sigmoid(W .* x))
                }
            "#;
            let (lp, _) = jit_grad(src2, "loss", &[&wp, &x], &[3]).unwrap();
            let (l0, _) = jit_grad(src, "loss", &[&w0, &x], &[3]).unwrap();
            let fd = (lp - l0) / eps;
            assert!(
                (fd - grads[0][k]).abs() < 0.05,
                "sigmoid grad[{}]: FD={} analytic={}", k, fd, grads[0][k]
            );
        }
    }

    #[test]
    fn jit_grad_matmul_relu() {
        // Matmul composed with ReLU — the standard neural-net layer pattern.
        // loss = sum(relu(W @ x))
        // W = [[1, -2], [3, 4]] (row-major), x = [[1], [1]] (shape [2,1])
        // W @ x = [-1, 7], relu -> [0, 7], sum -> 7.0
        // relu mask = [0, 1], so dW = [[0,0],[1,1]] (row-major: [0,0,1,1])
        let src = r#"
            @grad fn loss(!W: Tensor[f32, [2, 2]], x: Tensor[f32, [2, 1]]) -> f32 {
                sum(\>(W @ x))
            }
        "#;
        let w = [1.0_f32, -2.0, 3.0, 4.0];  // row-major [[1,-2],[3,4]]
        let x = [1.0_f32, 1.0];              // shape [2,1]
        let (loss, grads) = jit_grad(src, "loss", &[&w, &x], &[4]).unwrap();
        assert!(approx(loss, 7.0), "expected loss=7.0, got {}", loss);
        // grads[0] is flat row-major dW: [[0,0],[1,1]] -> [0,0,1,1]
        assert!(approx(grads[0][0], 0.0), "dW[0][0] expected 0.0, got {}", grads[0][0]);
        assert!(approx(grads[0][1], 0.0), "dW[0][1] expected 0.0, got {}", grads[0][1]);
        assert!(approx(grads[0][2], 1.0), "dW[1][0] expected 1.0, got {}", grads[0][2]);
        assert!(approx(grads[0][3], 1.0), "dW[1][1] expected 1.0, got {}", grads[0][3]);
    }

    #[test]
    fn jit_fomaml_multi_param() {
        // FOMAML where inner @grad fn has two mutable params (!W and !b).
        // inner: loss = sum((W .* x) .+ b)  -> g.W = x, g.b = ones
        // outer(!W, b, x): W1 = W - 0.5*g.W, b1 = b - 0.5*g.b
        //                  loss = sum(W1.*W1) + sum(b1.*b1)
        // With W=[1,1], b=[1,1], x=[1,1]:
        //   g.W=[1,1], g.b=[1,1]  (stop-gradient)
        //   W1=[0.5,0.5], b1=[0.5,0.5]
        //   loss = 0.5+0.5 = 1.0
        //   d(outer)/dW = 2*W1 = [1.0, 1.0]  (b1 path: b1 = b - 0.5*g.b, no dW)
        let src = r#"
            @grad fn inner(!W: Tensor[f32, [2]], !b: Tensor[f32, [2]], x: Tensor[f32, [2]]) -> f32 {
                sum((W .* x) .+ b)
            }
            @grad fn outer(!W: Tensor[f32, [2]], b: Tensor[f32, [2]], x: Tensor[f32, [2]]) -> f32 {
                let (_, g) = inner.fwd_bwd(W, b, x)
                let W1 = W .- g.W .* 0.5
                let b1 = b .- g.b .* 0.5
                sum(W1 .* W1) + sum(b1 .* b1)
            }
        "#;
        let w = [1.0_f32, 1.0];
        let b = [1.0_f32, 1.0];
        let x = [1.0_f32, 1.0];
        // The inner fwd_bwd leaves g.b in GRAD_SLOTS[1] (leaked; outer only
        // overwrites slot 0 for its own !W). So take_grads() returns 2 entries:
        // grads[0] = outer dW (slot 0), grads[1] = leaked inner g.b (slot 1).
        let (loss, grads) = jit_grad(src, "outer", &[&w, &b, &x], &[2, 2]).unwrap();
        assert!(approx(loss, 1.0), "expected loss=1.0, got {}", loss);
        assert!(approx(grads[0][0], 1.0), "dW[0] expected 1.0, got {:?}", grads[0]);
        assert!(approx(grads[0][1], 1.0), "dW[1] expected 1.0, got {:?}", grads[0]);
    }

    #[test]
    fn jit_grad_grad_tanh() {
        // Second derivative of sum(tanh(W)) wrt W at W=[0.5].
        // tanh'(x) = 1 - tanh²(x)
        // tanh''(x) = -2 * tanh(x) * (1 - tanh²(x))
        // At W=[0.5]: t = tanh(0.5) ≈ 0.4621
        //   tanh''(0.5) = -2 * 0.4621 * (1 - 0.4621²) ≈ -2 * 0.4621 * 0.7864 ≈ -0.727
        let src = r#"
            @grad @grad fn f(!W: Tensor[f32, [1]]) -> f32 {
                sum(tanh(W))
            }
        "#;
        let w = [0.5_f32];
        let (_, grads2) = jit_grad_grad(src, "f", &[&w], &[1]).unwrap();
        assert_eq!(grads2.len(), 1);
        let expected = -0.727_f32;
        assert!(
            (grads2[0][0] - expected).abs() < 0.05,
            "expected d²/dW²(tanh(W)) at W=0.5 ≈ {}, got {}",
            expected,
            grads2[0][0],
        );
    }

    #[test]
    fn jit_grad_grad_relu() {
        // Second derivative of relu is 0 everywhere (except at 0, which we treat as 0).
        // @grad @grad fn f(!W: Tensor[f32, [3]]) -> f32 { sum(\>(W)) }
        // All second derivatives should be 0.
        let src = r#"
            @grad @grad fn f(!W: Tensor[f32, [3]]) -> f32 {
                sum(\>(W))
            }
        "#;
        let w = [1.0_f32, -0.5, 2.0];
        let (_, grads2) = jit_grad_grad(src, "f", &[&w], &[3]).unwrap();
        assert_eq!(grads2.len(), 1);
        for (i, &g) in grads2[0].iter().enumerate() {
            assert!(
                g.abs() < 0.001,
                "expected d²/dW²(relu(W[{}])) = 0, got {}",
                i, g,
            );
        }
    }

    #[test]
    fn jit_grad_grad_sigmoid() {
        // Second derivative of sum(sigmoid(W)) wrt W.
        // sigmoid'(x) = s*(1-s) where s = sigmoid(x)
        // sigmoid''(x) = s*(1-s)*(1-2s)
        // At W=[0.0]: s=0.5, sigmoid''(0) = 0.5*0.5*(1-1.0) = 0.0
        // At W=[1.0]: s≈0.7311, sigmoid''(1) ≈ 0.7311*0.2689*(1-1.4622) ≈ -0.0908
        let src = r#"
            @grad @grad fn f(!W: Tensor[f32, [1]]) -> f32 {
                sum(sigmoid(W))
            }
        "#;
        // Test at W=0: second deriv should be 0
        let w_zero = [0.0_f32];
        let (_, grads2_zero) = jit_grad_grad(src, "f", &[&w_zero], &[1]).unwrap();
        assert_eq!(grads2_zero.len(), 1);
        assert!(
            grads2_zero[0][0].abs() < 0.01,
            "expected sigmoid''(0) = 0, got {}",
            grads2_zero[0][0],
        );
        // Test at W=1: second deriv ≈ -0.091
        let w_one = [1.0_f32];
        let (_, grads2_one) = jit_grad_grad(src, "f", &[&w_one], &[1]).unwrap();
        assert_eq!(grads2_one.len(), 1);
        let expected_at_1 = -0.091_f32;
        assert!(
            (grads2_one[0][0] - expected_at_1).abs() < 0.05,
            "expected sigmoid''(1) ≈ {}, got {}",
            expected_at_1,
            grads2_one[0][0],
        );
    }

