    // ─── #181: forge.uninit with model element type ───────────────────────────

    /// `forge.uninit[Layer, [3]]` allocates a ModelArray of size 3.
    #[test]
    fn jit_forge_uninit_model_array() {
        let src = r#"
model Layer { tag: i64 }
fn main() -> i64 {
    let l0 = Layer { tag: 10 }
    let l1 = Layer { tag: 20 }
    let l2 = Layer { tag: 30 }
    let !ls = forge.uninit[Layer, [3]]
    ls[0] = l0
    ls[1] = l1
    ls[2] = l2
    ls[0].tag + ls[1].tag + ls[2].tag
}
"#;
        // Note: ModelArray elements are model pointers; write then read.
        // We store pointers (l0, l1, l2) then load back by index.
        // But ls[i] = lj requires a store of the model pointer into the array.
        // Check if this syntax is supported; if not, use a simpler test.
        assert_eq!(jit_run_i64(src).unwrap(), 60);
    }

