    /// #263: `forge.uninit`/`zeros` with a *parameterized* model element type
    /// (`Bar[4]`) was rejected by the JIT ("element type must be a scalar type
    /// name") while the bare form (#181) worked. The parameterization doesn't
    /// change the ModelArray (a pointer array), so it now lowers identically.
    /// #266 then taught the interpreter to store into model arrays, so this is
    /// now a run/jit *parity* test (scalar-field store + read).
    #[test]
    fn jit_forge_uninit_parameterized_model_array() {
        let src = r#"
model Layer[N] { tag: i64 }
fn main() -> i64 {
    let l0 = Layer[4] { tag: 10 }
    let l1 = Layer[4] { tag: 20 }
    let l2 = Layer[4] { tag: 30 }
    let !ls = forge.uninit[Layer[4], [3]]
    ls[0] = l0
    ls[1] = l1
    ls[2] = l2
    ls[0].tag + ls[1].tag + ls[2].tag
}
"#;
        assert_eq!(jit_run_i64(src).unwrap(), 60);
        assert_jit_eq_interp(src); // #266: interp now agrees
    }

    /// #266: a *bare*-model array (the #181 JIT feature) is now also supported by
    /// the interpreter — store instances, read fields — so run and jit agree.
    /// Before #266 the interp errored ("cannot assign struct to tensor slice").
    #[test]
    fn model_array_store_read_parity() {
        let src = r#"
model Layer { tag: i64 }
fn main() -> i64 {
    let l0 = Layer { tag: 10 }
    let l1 = Layer { tag: 20 }
    let !ls = forge.uninit[Layer, [3]]
    ls[0] = l0
    ls[1] = l1
    ls[0].tag + ls[1].tag
}
"#;
        assert_eq!(jit_run_i64(src).unwrap(), 30);
        assert_jit_eq_interp(src);
    }

